-- GymTrack Pro: ejecutar una sola vez en el SQL Editor de Supabase.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz not null default now());
create table if not exists public.exercises(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,name text not null check(length(trim(name)) between 1 and 80),muscle_group text not null default 'General',equipment text,is_custom boolean not null default true,created_at timestamptz not null default now());
create unique index if not exists exercises_custom_name_unique on public.exercises(user_id,lower(name)) where user_id is not null;
create table if not exists public.routines(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(length(trim(name)) between 1 and 80),description text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.routine_exercises(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,routine_id uuid not null references public.routines(id) on delete cascade,exercise_id uuid not null references public.exercises(id) on delete restrict,position integer not null default 1 check(position>0),target_sets integer not null default 3 check(target_sets between 1 and 30),target_reps_min integer not null default 8 check(target_reps_min between 0 and 1000),target_reps_max integer not null default 12 check(target_reps_max between target_reps_min and 1000),rest_seconds integer not null default 90 check(rest_seconds between 0 and 3600),notes text,created_at timestamptz not null default now(),unique(routine_id,position));
create table if not exists public.workout_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,routine_id uuid references public.routines(id) on delete set null,name text not null default 'Entrenamiento',started_at timestamptz not null default now(),ended_at timestamptz,status text not null default 'completed' check(status in('active','completed','cancelled')),notes text,created_at timestamptz not null default now());
create table if not exists public.workout_exercises(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,session_id uuid not null references public.workout_sessions(id) on delete cascade,exercise_id uuid references public.exercises(id) on delete set null,exercise_name_snapshot text not null,position integer not null default 1 check(position>0),notes text,created_at timestamptz not null default now());
create table if not exists public.workout_sets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,workout_exercise_id uuid not null references public.workout_exercises(id) on delete cascade,set_number integer not null check(set_number>0),weight_kg numeric(8,2) not null default 0 check(weight_kg>=0),reps integer not null check(reps>=0),completed boolean not null default true,set_type text not null default 'normal' check(set_type in('normal','warmup','failure','drop')),rpe numeric(3,1) check(rpe between 0 and 10),rir integer check(rir between 0 and 10),duration_seconds integer check(duration_seconds>=0),distance_meters numeric(10,2) check(distance_meters>=0),notes text,created_at timestamptz not null default now(),unique(workout_exercise_id,set_number));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name','')); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security;alter table public.exercises enable row level security;alter table public.routines enable row level security;alter table public.routine_exercises enable row level security;alter table public.workout_sessions enable row level security;alter table public.workout_exercises enable row level security;alter table public.workout_sets enable row level security;
create policy profiles_select_own on public.profiles for select to authenticated using(id=(select auth.uid()));
create policy profiles_insert_own on public.profiles for insert to authenticated with check(id=(select auth.uid()));
create policy profiles_update_own on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy exercises_select_own on public.exercises for select to authenticated using(user_id=(select auth.uid()) or user_id is null);
create policy exercises_insert_own on public.exercises for insert to authenticated with check(user_id=(select auth.uid()));
create policy exercises_update_own on public.exercises for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy exercises_delete_own on public.exercises for delete to authenticated using(user_id=(select auth.uid()));
create policy routines_select_own on public.routines for select to authenticated using(user_id=(select auth.uid()));
create policy routines_insert_own on public.routines for insert to authenticated with check(user_id=(select auth.uid()));
create policy routines_update_own on public.routines for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy routines_delete_own on public.routines for delete to authenticated using(user_id=(select auth.uid()));
create policy routine_exercises_select_own on public.routine_exercises for select to authenticated using(user_id=(select auth.uid()));
create policy routine_exercises_insert_own on public.routine_exercises for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.routines r where r.id=routine_id and r.user_id=(select auth.uid())) and exists(select 1 from public.exercises e where e.id=exercise_id and (e.user_id=(select auth.uid()) or e.user_id is null)));
create policy routine_exercises_update_own on public.routine_exercises for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy routine_exercises_delete_own on public.routine_exercises for delete to authenticated using(user_id=(select auth.uid()));
create policy sessions_select_own on public.workout_sessions for select to authenticated using(user_id=(select auth.uid()));
create policy sessions_insert_own on public.workout_sessions for insert to authenticated with check(user_id=(select auth.uid()));
create policy sessions_update_own on public.workout_sessions for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy sessions_delete_own on public.workout_sessions for delete to authenticated using(user_id=(select auth.uid()));
create policy workout_exercises_select_own on public.workout_exercises for select to authenticated using(user_id=(select auth.uid()));
create policy workout_exercises_insert_own on public.workout_exercises for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.workout_sessions s where s.id=session_id and s.user_id=(select auth.uid())));
create policy workout_exercises_update_own on public.workout_exercises for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy workout_exercises_delete_own on public.workout_exercises for delete to authenticated using(user_id=(select auth.uid()));
create policy workout_sets_select_own on public.workout_sets for select to authenticated using(user_id=(select auth.uid()));
create policy workout_sets_insert_own on public.workout_sets for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.workout_exercises we where we.id=workout_exercise_id and we.user_id=(select auth.uid())));
create policy workout_sets_update_own on public.workout_sets for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy workout_sets_delete_own on public.workout_sets for delete to authenticated using(user_id=(select auth.uid()));
grant usage on schema public to authenticated;
grant select,insert,update,delete on public.profiles,public.exercises,public.routines,public.routine_exercises,public.workout_sessions,public.workout_exercises,public.workout_sets to authenticated;